      .m_axi_gmem_ARCACHE(m_axi_gmem1_ARCACHE),
      .m_axi_gmem_ARPROT(m_axi_gmem1_ARPROT),
      .m_axi_gmem_ARQOS(m_axi_gmem1_ARQOS),
      .m_axi_gmem_ARREGION(m_axi_gmem1_ARREGION),
      .m_axi_gmem_ARUSER(m_axi_gmem1_ARUSER),
      .m_axi_gmem_RVALID(m_axi_gmem1_RVALID),
      .m_axi_gmem_RREADY(m_axi_gmem1_RREADY),
      .m_axi_gmem_RDATA(m_axi_gmem1_RDATA),
      .m_axi_gmem_RLAST(m_axi_gmem1_RLAST),
      .m_axi_gmem_RID(m_axi_gmem1_RID),
      .m_axi_gmem_RUSER(m_axi_gmem1_RUSER),
      .m_axi_gmem_RRESP(m_axi_gmem1_RRESP),
      .m_axi_gmem_BVALID(m_axi_gmem1_BVALID),
      .m_axi_gmem_BREADY(m_axi_gmem1_BREADY),
      .m_axi_gmem_BRESP(m_axi_gmem1_BRESP),
      .m_axi_gmem_BID(m_axi_gmem1_BID),
      .m_axi_gmem_BUSER(m_axi_gmem1_BUSER));

  wire done_2, idle_2, ready_2;
  wire start_2 = pend[2];
  drain_mac_p_out_bind u_drain_mac_p_out_bind (
      .ap_clk(ap_clk),
      .ap_rst_n(ap_rst_n),
      .ap_start(start_2),
      .ap_done(done_2),
      .ap_idle(idle_2),
      .ap_ready(ready_2),
      .dst(drain_mac_p_out_bind_ptr),
      .steps(drain_mac_p_out_bind_steps),
      .in_0_dout(mac_p_out_bind_e_dout[0]),
      .in_0_empty_n(mac_p_out_bind_e_empty_n[0]),
      .in_0_read(mac_p_out_bind_e_read[0]),
      .in_1_dout(mac_p_out_bind_e_dout[1]),
      .in_1_empty_n(mac_p_out_bind_e_empty_n[1]),
      .in_1_read(mac_p_out_bind_e_read[1]),
      .in_2_dout(mac_p_out_bind_e_dout[2]),
      .in_2_empty_n(mac_p_out_bind_e_empty_n[2]),
      .in_2_read(mac_p_out_bind_e_read[2]),
      .in_3_dout(mac_p_out_bind_e_dout[3]),
      .in_3_empty_n(mac_p_out_bind_e_empty_n[3]),
      .in_3_read(mac_p_out_bind_e_read[3]),
      .in_4_dout(mac_p_out_bind_e_dout[4]),
      .in_4_empty_n(mac_p_out_bind_e_empty_n[4]),
      .in_4_read(mac_p_out_bind_e_read[4]),
      .in_5_dout(mac_p_out_bind_e_dout[5]),
      .in_5_empty_n(mac_p_out_bind_e_empty_n[5]),
      .in_5_read(mac_p_out_bind_e_read[5]),
      .in_6_dout(mac_p_out_bind_e_dout[6]),
      .in_6_empty_n(mac_p_out_bind_e_empty_n[6]),
      .in_6_read(mac_p_out_bind_e_read[6]),
      .in_7_dout(mac_p_out_bind_e_dout[7]),
      .in_7_empty_n(mac_p_out_bind_e_empty_n[7]),
      .in_7_read(mac_p_out_bind_e_read[7]),
      .m_axi_gmem_AWVALID(m_axi_gmem2_AWVALID),
      .m_axi_gmem_AWREADY(m_axi_gmem2_AWREADY),
      .m_axi_gmem_AWADDR(m_axi_gmem2_AWADDR),
      .m_axi_gmem_AWID(m_axi_gmem2_AWID),
      .m_axi_gmem_AWLEN(m_axi_gmem2_AWLEN),
      .m_axi_gmem_AWSIZE(m_axi_gmem2_AWSIZE),
      .m_axi_gmem_AWBURST(m_axi_gmem2_AWBURST),
      .m_axi_gmem_AWLOCK(m_axi_gmem2_AWLOCK),
      .m_axi_gmem_AWCACHE(m_axi_gmem2_AWCACHE),
      .m_axi_gmem_AWPROT(m_axi_gmem2_AWPROT),
      .m_axi_gmem_AWQOS(m_axi_gmem2_AWQOS),
      .m_axi_gmem_AWREGION(m_axi_gmem2_AWREGION),
      .m_axi_gmem_AWUSER(m_axi_gmem2_AWUSER),
      .m_axi_gmem_WVALID(m_axi_gmem2_WVALID),
      .m_axi_gmem_WREADY(m_axi_gmem2_WREADY),
      .m_axi_gmem_WDATA(m_axi_gmem2_WDATA),
      .m_axi_gmem_WSTRB(m_axi_gmem2_WSTRB),
      .m_axi_gmem_WLAST(m_axi_gmem2_WLAST),
      .m_axi_gmem_WID(m_axi_gmem2_WID),
      .m_axi_gmem_WUSER(m_axi_gmem2_WUSER),
      .m_axi_gmem_ARVALID(m_axi_gmem2_ARVALID),
      .m_axi_gmem_ARREADY(m_axi_gmem2_ARREADY),
      .m_axi_gmem_ARADDR(m_axi_gmem2_ARADDR),
      .m_axi_gmem_ARID(m_axi_gmem2_ARID),
      .m_axi_gmem_ARLEN(m_axi_gmem2_ARLEN),
      .m_axi_gmem_ARSIZE(m_axi_gmem2_ARSIZE),
      .m_axi_gmem_ARBURST(m_axi_gmem2_ARBURST),
      .m_axi_gmem_ARLOCK(m_axi_gmem2_ARLOCK),
      .m_axi_gmem_ARCACHE(m_axi_gmem2_ARCACHE),
      .m_axi_gmem_ARPROT(m_axi_gmem2_ARPROT),
      .m_axi_gmem_ARQOS(m_axi_gmem2_ARQOS),
      .m_axi_gmem_ARREGION(m_axi_gmem2_ARREGION),
      .m_axi_gmem_ARUSER(m_axi_gmem2_ARUSER),
      .m_axi_gmem_RVALID(m_axi_gmem2_RVALID),
      .m_axi_gmem_RREADY(m_axi_gmem2_RREADY),
      .m_axi_gmem_RDATA(m_axi_gmem2_RDATA),
      .m_axi_gmem_RLAST(m_axi_gmem2_RLAST),
      .m_axi_gmem_RID(m_axi_gmem2_RID),
      .m_axi_gmem_RUSER(m_axi_gmem2_RUSER),
      .m_axi_gmem_RRESP(m_axi_gmem2_RRESP),
      .m_axi_gmem_BVALID(m_axi_gmem2_BVALID),
      .m_axi_gmem_BREADY(m_axi_gmem2_BREADY),
      .m_axi_gmem_BRESP(m_axi_gmem2_BRESP),
      .m_axi_gmem_BID(m_axi_gmem2_BID),
      .m_axi_gmem_BUSER(m_axi_gmem2_BUSER));

  spmw_top dut (
      .ap_clk(ap_clk),
      .ap_rst_n(ap_rst_n),
      .mac_w_in_bind_dout(mac_w_in_bind_e_dout),
      .mac_w_in_bind_empty_n(mac_w_in_bind_e_empty_n),
      .mac_w_in_bind_read(mac_w_in_bind_e_read),
      .mac_a_in_bind_dout(mac_a_in_bind_e_dout),
      .mac_a_in_bind_empty_n(mac_a_in_bind_e_empty_n),
      .mac_a_in_bind_read(mac_a_in_bind_e_read),
      .mac_p_out_bind_din(mac_p_out_bind_e_din),
      .mac_p_out_bind_write(mac_p_out_bind_e_write),
      .mac_p_out_bind_full_n(mac_p_out_bind_e_full_n));

  // Exactly one job per feeder per invocation.
  //
  // Holding `ap_start` high until the slowest feeder is done makes an
  // `ap_ctrl_hs` IP take the job again the moment it frees up, and
  // gating on `ap_done` does not help -- the IP accepts on `ap_ready`,
  // which it asserts in the same cycle. A feeder that runs twice
  // writes its family twice, and the array, fed tokens it never asked
  // for, stalls with nothing to say about why. So the start is a
  // one-shot: raised when the kernel is kicked, dropped the moment
  // that feeder accepts.
  reg ap_start_d;
  wire kick = ap_start & ~ap_start_d;
  always @(posedge ap_clk) ap_start_d <= ap_rst_n ? ap_start : 1'b0;
  always @(posedge ap_clk) begin
    if (rst) begin
      fin <= 0; pend <= 0;
    end else if (ap_ready) begin
      // the job is over; a start queued for this very cycle kicks now
      fin <= 0; pend <= {3{kick}};
    end else begin
      if (kick) pend[0] <= 1'b1;
      else if (ready_0) pend[0] <= 1'b0;
      if (done_0) fin[0] <= 1'b1;
      if (kick) pend[1] <= 1'b1;
      else if (ready_1) pend[1] <= 1'b0;
      if (done_1) fin[1] <= 1'b1;
      if (kick) pend[2] <= 1'b1;
      else if (ready_2) pend[2] <= 1'b0;
      if (done_2) fin[2] <= 1'b1;
    end
  end
  // feed_mac_w_in_bind: 64 bits a step, 512-bit beats
  wire [31:0] want_0 = ((feed_mac_w_in_bind_steps * 32'd64) + 32'd511) >> 9;
  reg [31:0] moved_0;
  wire beat_0 = m_axi_gmem0_RVALID & m_axi_gmem0_RREADY;
  always @(posedge ap_clk) begin
    if (rst | ap_ready) moved_0 <= 32'd0;
    else if (beat_0) moved_0 <= moved_0 + 32'd1;
  end
  // feed_mac_a_in_bind: 64 bits a step, 512-bit beats
  wire [31:0] want_1 = ((feed_mac_a_in_bind_steps * 32'd64) + 32'd511) >> 9;
  reg [31:0] moved_1;
  wire beat_1 = m_axi_gmem1_RVALID & m_axi_gmem1_RREADY;
  always @(posedge ap_clk) begin
    if (rst | ap_ready) moved_1 <= 32'd0;
    else if (beat_1) moved_1 <= moved_1 + 32'd1;
  end
  // drain_mac_p_out_bind: 256 bits a step, 512-bit beats
  wire [31:0] want_2 = ((drain_mac_p_out_bind_steps * 32'd256) + 32'd511) >> 9;
  reg [31:0] moved_2;
  wire beat_2 = m_axi_gmem2_WVALID & m_axi_gmem2_WREADY;
  reg [15:0] wout_2;  // bursts issued and not yet answered
  always @(posedge ap_clk) begin
    if (rst | ap_ready) moved_2 <= 32'd0;
    else if (beat_2) moved_2 <= moved_2 + 32'd1;
    if (rst) wout_2 <= 16'd0;
    else wout_2 <= wout_2 + ((m_axi_gmem2_AWVALID & m_axi_gmem2_AWREADY) ? 16'd1 : 16'd0) - ((m_axi_gmem2_BVALID & m_axi_gmem2_BREADY) ? 16'd1 : 16'd0);
  end
  assign ap_done  = (&fin) & (moved_0 == want_0) & (moved_1 == want_1) & (moved_2 == want_2) & (wout_2 == 16'd0);
  assign ap_ready = ap_done;
  assign ap_idle  = idle_0 & idle_1 & idle_2;
endmodule
